List<Integer> numbers = new ArrayList<>();
int primitive = 42;

// Autoboxing: compiler converts to Integer.valueOf(primitive)
numbers.add(primitive);

// Unboxing: compiler converts to numbers.get(0).intValue()
int result = numbers.get(0);

// The 'Gotcha':
Integer a = 1000;
Integer b = 1000;
System.out.println(a == b); // false (different heap objects)
System.out.println(a.equals(b)); // true (value comparison)
